-- Producto: Base Aura Trendy
INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('13a97a63-8114-4cc3-8804-3b40cbd23fd6', 'Base Aura Trendy', 30000.0, 'La Base Aura Trendy Ref BAT2272 La base de maquillaje que logra lo que pocas consiguen: acabado mate profesional y cobertura buildable sin sensación grasa ni pesada durante todo el día - Su fórmula está desarrollada para pieles mixtas a grasas que necesitan control del brillo sin sacrificar comodidad. - El acabado mate mantiene la piel pulida durante horas sin que necesites retocar constantemente. - La cobertura es buildable: una capa da un resultado de piel unificada y natural; dos capas en zonas específicas dan mayor intensidad sin el efecto "máscara" que dan las bases de cobertura plana. - La sensación en la piel es ligera y cómoda — el maquillaje que se olvida que se lleva puesto hasta que te ves al espejo. - Disponible en varios tonos para la diversidad de pieles colombianas. Disponible en 9 tonos.', 'rostro', '/images/products/base-aura-trendy.jpg', 1, 0, 1, 2, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
INSERT INTO ProductImage (id, productId, url, sortOrder, altText, createdAt, updatedAt) VALUES ('f7c4833d-7f8d-436e-afbc-76fd227f7702', '13a97a63-8114-4cc3-8804-3b40cbd23fd6', '/images/products/base-aura-trendy.jpg', 0, 'Base Aura Trendy', '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
