-- Producto: Polvo de Hadas Trendy 15g
INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('e1abfe73-3418-4999-9d5b-7afcbcdff573', 'Polvo de Hadas Trendy 15g', 12000.0, 'El polvo de hadas es un producto indispensable si te gusta el brillo. Este es el clásico, de tonalidad plateada. Su aplicador en esponja facilita su aplicación en rostro, hombros, escote o donde desees un toque radiante.', 'rostro', '/images/products/polvo-de-hadas-trendy-15g.jpg', 1, 0, 1, 2, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
INSERT INTO ProductImage (id, productId, url, sortOrder, altText, createdAt, updatedAt) VALUES ('7fd33f78-42fe-486f-9d9b-fb16f5084d8e', 'e1abfe73-3418-4999-9d5b-7afcbcdff573', '/images/products/polvo-de-hadas-trendy-15g.jpg', 0, 'Polvo de Hadas Trendy 15g', '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');

-- Producto: Rubor en Barra Trendy Blush Love
INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('f0d586e7-1e8f-4edb-8edf-ae9b00c2d14d', 'Rubor en Barra Trendy Blush Love', 15000.0, 'Rubor En Barra Blush Love Ref BL07 - ¡El rubor en barra en forma de corazón que dejará enamoradas tus mejillas! El rubor de maquillaje, también conocido como blush, sirve principalmente para devolverle el color, la vitalidad y la dimensión al rostro. Su función es dar un efecto rosadito simulando el color natural de esta zona, y dependiendo de dónde lo apliques, ayuda a levantar visualmente los pómulos o suavizar las facciones. Viene en 2 tonos universales que te llegan surtidos, pero los dos son hermosos. El empaque es demasiado tierno y funcional, ¡puedes llevarlo siempre contigo! Su textura es cremosa; puedes aplicar con brocha o, si prefieres, directamente en el rostro. Al ser un rubor en crema, tiene mayor durabilidad en el rostro, pero un plus es sellarlo con polvo para que quede intacto. Su pigmentación es increíble.', 'rostro', '/images/products/rubor-en-barra-trendy-blush-love.jpg', 1, 0, 1, 2, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
INSERT INTO ProductImage (id, productId, url, sortOrder, altText, createdAt, updatedAt) VALUES ('f0944dba-0d9b-4c66-950f-948de0156952', 'f0d586e7-1e8f-4edb-8edf-ae9b00c2d14d', '/images/products/rubor-en-barra-trendy-blush-love.jpg', 0, 'Rubor en Barra Trendy Blush Love', '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');

-- Producto: Fijador Trendy Cosmic Night Trendy
INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('211e3242-5b58-4222-bdd9-32205bb73932', 'Fijador Trendy Cosmic Night Trendy', 25000.0, 'Fijador Cosmic Night Ref CN09 - ¡Que tu maquillaje dure tanto como tus planes! El fijador Cosmic ayuda a mantener tu maquillaje intacto por más tiempo, protegiéndolo del calor, la humedad y el desgaste natural del día. Es un spray ligero que se distribuye uniformemente sobre el rostro, ayudando a sellar el maquillaje sin dejar sensación pesada. Además, su acabado mate contribuye a controlar el exceso de brillo para que tu piel luzca fresca y tu maquillaje impecable durante horas. Rápido secado y excelente duración. Un imprescindible para quienes buscan mayor duración y un acabado más pulido en su maquillaje.', 'rostro', '/images/products/fijador-trendy-cosmic-night-trendy.jpg', 1, 0, 1, 2, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
INSERT INTO ProductImage (id, productId, url, sortOrder, altText, createdAt, updatedAt) VALUES ('014b1c42-2b81-49af-bab7-519fec2a8c00', '211e3242-5b58-4222-bdd9-32205bb73932', '/images/products/fijador-trendy-cosmic-night-trendy.jpg', 0, 'Fijador Trendy Cosmic Night Trendy', '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');

-- Producto: Brillo de Labios Lip Oil Pretty Things Trendy
INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('49de99c8-b65f-41cf-89dd-82e67f55ac8e', 'Brillo de Labios Lip Oil Pretty Things Trendy', 10000.0, 'Las Tintas Pretty Things llegan para las amantes a los labios naturales pero con color. Su pigmentación es construible, así que entre más apliques más se notará el color. Tienen una textura suave y ligera, así que se difuminan suavemente sobre tus labios. Son 6 tonos diferentes, elige tu color favorito. Sus colores son rojizos y uno violeta, ideales para aportar un leve color. Su textura es espesa, así que se esparce sobre tus labios fácilmente.', 'labial', '/images/products/brillo-de-labios-lip-oil-pretty-things-trendy.jpg', 1, 0, 1, 1, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
INSERT INTO ProductImage (id, productId, url, sortOrder, altText, createdAt, updatedAt) VALUES ('6757ec22-5785-4d88-85dd-260629c2f12e', '49de99c8-b65f-41cf-89dd-82e67f55ac8e', '/images/products/brillo-de-labios-lip-oil-pretty-things-trendy.jpg', 0, 'Brillo de Labios Lip Oil Pretty Things Trendy', '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
