INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('8e56a0b4-4c37-42ec-b61b-6c6c3c1c9144', 'Tinta con Escarcha Be Mine', 10000.0, 'Tinta Con Escarcha Be Mine Ref TEB1745 - ¡Las tintas le dan el color perfecto a tus labios! Unos labios de impacto gracias a la tinta Be mine. Su textura es suave y se difumina sobre tus labios de forma perfecta. Aporta un acabado con destellos dorados. Su durabilidad es excelente. Viene en un tono rojo cereza.', 'labial', '/images/products/tinta-con-escarcha-be-mine.jpg', 1, 0, 1, 2, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
