INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('e222de68-6039-44bb-80c6-0ec45dd5ef04', 'Gel Fijador de Cejas Glow Trendy', 15000.0, 'Gel Fijador De Cejas Glow Ref CBG2167 - Logra que tus cejas estén peinaditas y en su lugar con el fijador de cejas Brow glow. -Su formato de empaque colapsible te permite aprovechar al máximo tu producto; además, contiene un cepillo suave que actúa como pulidor y aplicador a la vez. -Este producto no aporta color, así que puedes dejarlas al natural o rellenar espacios con tu técnica favorita una vez seque el fijador. -Es de fijación media.', 'ojos', '/images/products/gel-fijador-de-cejas-glow-trendy.jpg', 1, 0, 1, 5, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
