-- Producto: Brillo Labial Furia Trendy
INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('9644252c-b6c9-4b28-b4ab-b8a5d40d3f3d', 'Brillo Labial Furia Trendy', 15000.0, 'Brillo Furia Ref DYT2571 - ¡Tu favorito para labios, ahora en versión individual! - La Tinta de Labios Furia de Trendy está diseñada para quienes aman un color intenso con un acabado hermoso y duradero. - Su textura ligeramente oleosa permite que se deslice con facilidad, logrando una aplicación uniforme sin sensación pesada ni pegajosa. - Aporta un tono vibrante que se fija en los labios dejando un efecto natural. - Perfecta para usar sola con acabado difuminado o como base para potenciar tu gloss favorito. - Es la tinta perfecta para lograr looks versátiles, en tendencia y con la actitud Furia que te encanta.', 'labial', '/images/products/brillo-labial-furia-trendy.jpg', 1, 0, 1, 2, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
