-- Producto: Tinta de Labios Princesas Bella
INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('64cf566f-b706-4144-8f79-5558d2acc8ea', 'Tinta de Labios Princesas Bella', 15000.0, 'Tinta De Labios Princesas Bella Ref Dy2214 La tinta de labios inspirada en Disney Princesas que faltaba en tu colección. - Aporta un tono borgoña rojizo a tus labios que, gracias a su textura ligera, puedes difuminar suavemente y construir su intensidad según el look que desees. - Resalta tus labios mientras crea un acabado fresco y duradero, ideal para el día o la noche. - Su empaque es hermoso y muy girly, con el tamaño perfecto para llevar en tu cosmetiquera o bolso.', 'labial', '/images/products/tinta-de-labios-princesas-bella.jpg', 1, 0, 1, 1, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
