-- Producto: Labial Doble Vaquero Toy Story Trendy
INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('a7e38480-9748-4538-b659-68d6979c189c', 'Labial Doble Vaquero Toy Story Trendy', 15000.0, 'Labial Doble Vaquero Toy Story Dyt2648 - Dos formas de expresar tu estilo en un solo producto. El Labial Doble Toy Story combina color y versatilidad para crear diferentes looks, permitiéndote mezclar el acabado que mejor se adapte a cada ocasión. Su práctica presentación reúne dos opciones en un solo producto, por un costado encontrarás un labial semi mate y por el otro el mismo tono pero con acabado satinado, ideal para acompañarte desde el día hasta la noche con comodidad y personalidad. Disponible en 3 tonos, rosado, café y uno naranja. Inspirado en el mágico universo de Toy Story, es perfecto para quienes disfrutan experimentar con su maquillaje y llevar siempre una alternativa para complementar cualquier estilo.', 'labial', '/images/products/labial-doble-vaquero-toy-story-trendy.jpg', 1, 0, 1, 1, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
