INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('82d9c855-4b9f-4353-af70-a3bdd857a2fa', 'Lip Balm Glitter Hamm Trendy', 15000.0, 'Lip Balm Glitter Ham Ref Dyt2683 - Mágico desde el empaque hasta el color. Consiente tus labios con color y un delicado toque de brillo. El Lip Balm Ham combina cuidado, belleza e innovación gracias a su textura de gelatina; son 3 tonos diferentes en su barra, pero el color es el mismo. Te ayuda a mantener los labios suaves, cómodos y con una apariencia saludable. Su textura ligera se desliza fácilmente, proporcionando una sensación confortable y un acabado natural ideal para cualquier ocasión.', 'labial', '/images/products/lip-balm-glitter-hamm-trendy.jpg', 1, 0, 1, 1, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
