INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('a62ac10a-98aa-4ffb-a19d-99b1106c3a90', 'Rubor en Crema Lotso', 15000.0, 'Consigue unas mejillas naturalmente radiantes con el Rubor en Crema Lotso. Su textura cremosa y ligera se funde fácilmente con la piel, permitiendo modular la intensidad del color para un acabado fresco y jugoso.', 'rostro', '/images/products/rubor-en-crema-lotso.jpg', 1, 0, 1, 1, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
