-- Producto: Primer Menta 60ml Trendy
INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('0bda7837-8cba-49db-8b10-ce6c92ae9338', 'Primer Menta 60ml Trendy', 15000.0, 'Primer Menta Trendy 60ml Ref PMT1371 - No más piel acartonada o cuarteada al momento de aplicar tu maquillaje. Aplicar Primer antes de tu base ayuda a mejorar la adherencia y prolongar su duración, Este tiene un efecto mentolado y ácido hialurónico que permite que tu piel esté fresca y radiante durante todo el día, dándole un acabado superior a tu maquillaje. Su textura en gel es humectante y se absorbe con facilidad en tu piel. No deja sensación grasa ni pesada.', 'rostro', '/images/products/primer-menta-60ml-trendy.jpg', 1, 0, 1, 2, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
INSERT INTO ProductImage (id, productId, url, sortOrder, altText, createdAt, updatedAt) VALUES ('81075e81-4220-44ac-bd27-868063cae51d', '0bda7837-8cba-49db-8b10-ce6c92ae9338', '/images/products/primer-menta-60ml-trendy.jpg', 0, 'Primer Menta 60ml Trendy', '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');

-- Producto: Primer Aloha Trendy
INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('7e2b36f5-581f-4963-9049-b4716b516178', 'Primer Aloha Trendy', 15000.0, 'Primer Aloha Ref PAT1894 - Los primers son una herramienta para asegurar un mejor acabado en nuestros maquillajes. El primer o prebase en el maquillaje sirve para preparar la piel, actuando como un puente entre tu rostro y el maquillaje. Su función principal es unificar la textura, minimizar los poros, controlar el brillo y hacer que tu maquillaje dure mucho más tiempo intacto. En esta ocasión traemos el primer Aloha, formulado con ácido hialurónico, lo que permite mantener hidratada tu piel durante el día. Su textura es tipo gel a base de agua, así que es perfecto para todo tipo de piel. Su aroma es neutro. Sus componentes permiten una mayor adherencia y duración de los productos durante el día.', 'rostro', '/images/products/primer-aloha-trendy.jpg', 1, 0, 1, 1, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
