INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('ab9be47e-822d-494b-a4fd-c66ebf981023', 'Kit Splash y Crema The Perfect Match 03 Style', 15000.0, 'Kit Splash Y Crema The Perfect Ref PMS1932 Fragancia Floral-Frutal Cálida y Vibrante - Sumérgete en un mundo de sensaciones con nuestra fragancia floral-frutal, una mezcla cálida y vibrante que despierta los sentidos. - Las notas de salida de grosella negra, higo, flor de azahar y jazmín se combinan en una sinfonía olfativa que realza un aroma fresco e intenso. - Diseñada para la mujer moderna que busca expresar su personalidad, esta fragancia fascinante emana elegancia y feminidad. - Complementa tu fragancia con nuestra crema de manos, que ofrece un aroma suave y armonioso. - Su fórmula ligera proporciona una hidratación profunda sin dejar sensación grasosa, mientras que los destellos sutiles iluminan tu piel', 'skincare', '/images/products/kit-splash-y-crema-the-perfect-match-03-style.jpg', 1, 0, 1, 1, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
