-- Producto: Cepillo Pulidor Trendy
INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('197ebb70-d6fc-48c6-941c-4fd67e5021f9', 'Cepillo Pulidor Trendy', 8000.0, 'El secreto del clean look. Consigue el estilo clean look y pulido que siempre has querido con nuestro cepillo pulidor. Está diseñado para lograr un acabado elegante y sofisticado en tus peinados. Sus cerdas suaves y densas permiten que el cabello tome forma y una textura lisa al momento de peinar, disminuyendo el frizz y logrando una apariencia pulida. Es muy versátil, perfecto para todo tipo de cabello. Su diseño es liviano y cómodo, esto lo hace de fácil manejo. Por un costado encuentras las cerdas gruesas para pulir y por el otro encuentras un cabo metálico que facilitará la separación del cabello para crear distintos peinados. -', 'accesorio-de-maquillaje', '/images/products/cepillo-pulidor-trendy.jpg', 1, 0, 1, 1, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
INSERT INTO ProductImage (id, productId, url, sortOrder, altText, createdAt, updatedAt) VALUES ('3c6d0c3b-df6e-462b-8c05-49eed7736230', '197ebb70-d6fc-48c6-941c-4fd67e5021f9', '/images/products/cepillo-pulidor-trendy.jpg', 0, 'Cepillo Pulidor Trendy', '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');

-- Producto: Kit Pelo Fabulosa Trendy
INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('df9b32ab-46ef-4711-9ae9-3369d442e016', 'Kit Pelo Fabulosa Trendy', 10000.0, 'Kit Pelo Fabulosa Ref Kfp2288 Luciremos el peinado perfecto, porque tenemos las herramientas indicadas. ¡Domina cada look con precisión y estilo! - Este Kit de Cepillos Trendy es el aliado perfecto para lograr desde peinados pulidos hasta estilos más elaborados. - Este set completo incluye herramientas claves para un acabado impecable: - 1 Cepillo pulidor mediano: ideal para alisar, dar forma y controlar el frizz en secciones más amplias de cabello. - 1 Cepillo pulidor pequeño doble + peinilla pequeña: perfecto para detalles, retoques en bordes y peinados definidos como trenzas o baby hairs. - 1 Peinilla con cabo metálico: facilita una partición precisa del cabello, esencial para peinados con secciones bien marcadas. - Este kit será tu mejor amigo todas las mañanas, controla y da estilo a tu cabello.', 'accesorio-de-maquillaje', '/images/products/kit-pelo-fabulosa-trendy.jpg', 1, 0, 1, 2, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
INSERT INTO ProductImage (id, productId, url, sortOrder, altText, createdAt, updatedAt) VALUES ('8255989d-02aa-44d0-9910-95bd18e56a18', 'df9b32ab-46ef-4711-9ae9-3369d442e016', '/images/products/kit-pelo-fabulosa-trendy.jpg', 0, 'Kit Pelo Fabulosa Trendy', '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');

-- Producto: Brocha Individual Cejas y Pestañas Trendy
INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('3e5006cb-58d6-44fc-a8f0-12b8a31952e6', 'Brocha Individual Cejas y Pestañas Trendy', 8000.0, '¡Necesidad desbloqueada, cejas y pestañas perfectas! No hay nada que arruine más un maquillaje hermoso que unas cejas despeinadas con parches de producto o unas pestañas llenas de grumos pegajosos que te hacen ver la mirada pesada y cansada. ¡Es hora de unirte al club de las miradas de impacto! Nuestra brocha 2 en 1 es el secreto mejor guardado que necesitas para que mantengas impecables todos los días tus cejas y pestañas sin esfuerzo. Por un lado, tienes una brocha angular ultra precisa ideal para rellenar y diseñar, y por el otro, un cepillo espectacular para peinar y difuminar. Es una herramienta de calidad profesional, y sus colores en negro con detalles dorados la hacen ver muy luxury, aportando todo el glamour y la elegancia que tu cosmetiquera se merece.', 'accesorio-de-maquillaje', '/images/products/brocha-individual-cejas-y-pestanas-trendy.jpg', 1, 0, 1, 2, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
