INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('f61caafd-1252-401b-88c8-7bd0bf54e65f', 'Corrector Ojeras Hidratante Rebel Girl Trendy', 12000.0, 'Corrector Hidrante Rebel Girl Ref Crg1420 - ¡Un corrector perfecto para el día a día! Cubre y disimula tus imperfecciones gracias a nuestro corrector Rebel Girl. Tiene una cobertura media - alta. Es muy cremosito. Te deja un acabado mate. Al cubrir las ojeras logra que la zona del contorno de los ojos se vea mucho más radiante. No es pesado. Aporta una cobertura uniforme sin dejar parches Viene en 3 tonos.', 'rostro', '/images/products/corrector-ojeras-hidratante-rebel-girl-trendy.jpg', 1, 0, 1, 2, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
