INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('5d4c8de1-2126-4087-acfa-3f09cc01157b', 'Pompón Iluminador Cotton Trendy', 10000.0, 'Pompón Cotton Ref PCT1798 - Brillo que enamora Si amas una piel glowy, este pompón será tu nuevo favorito. Su pigmento plateado brillante aporta un toque de luminosidad que transforma cualquier look. Su diseño inspirado en el algodón de azúcar no solo es adorable: evita derrames y mantiene el producto en su lugar, para llevarlo contigo sin preocupaciones. ¡Un súper tip: cuida tu Pompón Cotton de fuentes de calor o de olor para que te rinda al máximo y te dure muchísimo tiempo!', 'rostro', '/images/products/pompon-iluminador-cotton-trendy.jpg', 1, 0, 1, 2, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
