INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('ac84e3d0-f809-400b-b877-8e429f205c66', 'Iluminador Líquido Brilla', 10000.0, 'Iluminador Líquido Brilla Ref SLB1927 - ¡Deslumbra tus maquillajes de la mano de este iluminador! Agrega un glowy perfecto pero con un plus y es que es que se ve muy sutil en tus looks. Su textura es cremosa y muy ligera. Al aplicarlo se difumina fácil. No te deja sensación pesada. Viene en un tono único champán precioso.', 'rostro', '/images/products/iluminador-liquido-brilla.jpg', 1, 0, 1, 1, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
