INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('c3338efb-f533-403c-ab63-9bf49ff1f446', 'Kit x3 Gloss Mood Pills Trendy', 15000.0, 'Estas píldoras son el remedio perfecto para el síndrome de maquillaje aburrido. Kit de 3 glosses con el glow más precioso de todos. Utilízalas para devolverle el brillo y glamour a tus looks. En cada cajita encuentras 3 tonos diferentes, entre oro rosa, rosado y uno con destellos dorados.', 'labial', '/images/products/kit-x-3-gloss-mood-pills-trendy.jpg', 1, 0, 1, 2, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
