INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('5b943671-344b-4daf-9a34-4f28aac3e630', 'Tinta Gloss Corazón Trendy', 5000.0, 'Tinta Gloss Corazón Ref TGT1896 - Descubre un nuevo formato de Tinta de Labios de larga duración. Disponible en una gama vibrante de tonos rojizos, esta fórmula innovadora de textura aterciopelada y cremosa, que se desliza suavemente para crear un acabado mate y sin transferencias lo que hará que perdure todo el día. No solo proporciona un color intenso, sino que también mantiene tus labios suaves y flexibles. Perfecta para cualquier ocasión, nuestra Tinta Gloss Tint es el complemento ideal para tu rutina de maquillaje, garantizando una aplicación fácil y resultados duraderos desde el primer toque.', 'labial', '/images/products/tinta-gloss-corazon-trendy.jpg', 1, 0, 1, 6, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
