INSERT INTO Product (id, name, price, description, category, mainImage, isNew, isFeatured, inStock, stock, createdAt, updatedAt) VALUES ('9640dd99-8fed-4675-83f2-a8aa9f5cec5c', 'Brillo Mágico Doble Perfect Match Trendy', 8000.0, 'Brillo Magico Doble Perfect Match Ref Bpm1426 - Dos acabados, un solo producto. Perfect Match combina un labial en barra y un labial líquido en un formato práctico y versátil. Puedes utilizarlos por separado o combinarlos para crear diferentes looks. Su fórmula aporta color, brillo y una sensación cómoda en los labios, desde un acabado natural hasta uno más intenso.', 'labial', '/images/products/brillo-magico-doble-perfect-match-trendy.jpg', 1, 0, 1, 4, '2026-10-23T10:00:00.000Z', '2026-10-23T10:00:00.000Z');
